-- Raw legacy archive tables
DROP TABLE IF EXISTS `legacy_complaint_entries`;
CREATE TABLE `legacy_complaint_entries` (
  `legacy_row_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id` INT NULL,
  `reference_no` VARCHAR(25) NULL,
  `complaint_date` DATE NULL,
  `name` VARCHAR(250) NULL,
  `mobile_no` VARCHAR(20) NULL,
  `communic_address` VARCHAR(500) NULL,
  `loc_name` VARCHAR(500) NULL,
  `ward` VARCHAR(100) NULL,
  `zone` VARCHAR(100) NULL,
  `door_no` VARCHAR(500) NULL,
  `alter_address` VARCHAR(500) NULL,
  `assess_no` VARCHAR(100) NULL,
  `department_name` VARCHAR(500) NULL,
  `complaint_category` VARCHAR(500) NULL,
  `complaint_descrip` LONGTEXT NULL,
  `attach1` VARCHAR(500) NULL,
  `attach2` VARCHAR(500) NULL,
  `attach3` VARCHAR(500) NULL,
  `attach4` VARCHAR(500) NULL,
  `created_at` VARCHAR(30) NULL,
  `updated_at` VARCHAR(30) NULL,
  `user_type` VARCHAR(250) NULL,
  `status` VARCHAR(250) NULL,
  `source` VARCHAR(250) NULL,
  `is_created` TINYINT NULL,
  `is_deleted` TINYINT NULL,
  PRIMARY KEY (`legacy_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legacy_dept_master`;
CREATE TABLE `legacy_dept_master` (
  `legacy_row_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `sno` INT NULL,
  `department_name` VARCHAR(150) NULL,
  `complaint_category` VARCHAR(500) NULL,
  `officer_name` VARCHAR(250) NULL,
  `ward` TEXT NULL,
  `mobile_number` VARCHAR(20) NULL,
  PRIMARY KEY (`legacy_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legacy_feedback`;
CREATE TABLE `legacy_feedback` (
  `legacy_row_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id` INT NULL,
  `name` VARCHAR(250) NULL,
  `mobile_no` VARCHAR(20) NULL,
  `email` VARCHAR(250) NULL,
  `feedback` LONGTEXT NULL,
  `created_at` VARCHAR(30) NULL,
  PRIMARY KEY (`legacy_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legacy_officer_master`;
CREATE TABLE `legacy_officer_master` (
  `legacy_row_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `sno` INT NULL,
  `officer_name` VARCHAR(250) NULL,
  `department_name` VARCHAR(150) NULL,
  `mobile_no` VARCHAR(20) NULL,
  `zone` TEXT NULL,
  `ward` TEXT NULL,
  PRIMARY KEY (`legacy_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legacy_priority_master`;
CREATE TABLE `legacy_priority_master` (
  `legacy_row_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `sno` INT NULL,
  `department_name` VARCHAR(150) NULL,
  `complaint_category` VARCHAR(500) NULL,
  `no_of_days` INT NULL,
  PRIMARY KEY (`legacy_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legacy_street_master`;
CREATE TABLE `legacy_street_master` (
  `legacy_row_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id` INT NULL,
  `street_name` VARCHAR(500) NULL,
  `ward` INT NULL,
  `zone` INT NULL,
  PRIMARY KEY (`legacy_row_id`),
  KEY `idx_legacy_street_id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legacy_import_conflicts`;
CREATE TABLE `legacy_import_conflicts` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `conflict_type` VARCHAR(100) NOT NULL,
  `source_table` VARCHAR(100) NOT NULL,
  `source_key` VARCHAR(500) NULL,
  `details` LONGTEXT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `legacy_complaint_entries` (`id`, `reference_no`, `complaint_date`, `name`, `mobile_no`, `communic_address`, `loc_name`, `ward`, `zone`, `door_no`, `alter_address`, `assess_no`, `department_name`, `complaint_category`, `complaint_descrip`, `attach1`, `attach2`, `attach3`, `attach4`, `created_at`, `updated_at`, `user_type`, `status`, `source`, `is_created`, `is_deleted`) VALUES
